 ap=argparse.ArgumentParser();ap.add_argument('--ground-body',type=Path,required=True);ap.add_argument('--trial-report',type=Path,required=True);ap.add_argument('--trial',type=int,default=0);args=ap.parse_args();args.ground_body=args.ground_body if args.ground_body.is_absolute()else ROOT/args.ground_body;args.trial_report=args.trial_report if args.trial_report.is_absolute()else ROOT/args.trial_report
